    I love tunnel shaders and this one uses some 
    polar rep and a few folds to make a neat shape.
    Added some glowing shapes and a modified DOF trick
    I saw @Nusan do https://www.shadertoy.com/view/3sXyRN


    Polar rep stuff from Mercury Sexy
    http://mercury.sexy/hg_sdf/

    Polar Fractal Tunnel
    01/19/2025  @byt3_m3chanic 

*/

#define R iResolution
#define M iMouse
#define T iTime

#define PI  3.14159265359
#define PI2 6.28318530718

#define MIN_DIST .0005
#define MAX_DIST 90.

mat2 rz;
vec3 hit,hp;
float travelSpeed =0.,glow=0.,sglow=0.;
const float sp = 7., hf = sp/2., qt = hf/2.;

mat2 rot (float a) { return mat2(cos(a),sin(a),-sin(a),cos(a)); }
float hash21( vec2 p ) { return fract(sin(dot(p,vec2(23.43,84.21))) *4832.3234); }
float box(vec3 p, vec3 b){
    vec3 d = abs(p)-b;
    return length(max(d,0.))+min(max(d.x,max(d.y,d.z)),.0);
}

// http://mercury.sexy/hg_sdf/
// Repeat around the origin by a fixed angle.
float pModPolar(inout vec2 p, float repetitions) {
    float angle = 2.*PI/repetitions;
    float a = atan(p.y, p.x) + angle/2.;
    float r = length(p);
    float c = floor(a/angle);
    a = mod(a,angle) - angle/2.;
    p = vec2(cos(a), sin(a))*r;
    // For an odd number of repetitions, fix cell index of the cell in -x direction
    // (cell index would be e.g. -5 and 5 in the two halves of the cell):
    if (abs(c) >= (repetitions/2.)) c = abs(c);
    return c;
}

vec2 path(in float z){ 
    vec2 p1 =vec2(2.3*sin(z * .153), 1.4*cos(z * .223));
    vec2 p2 =vec2(1.2*sin(z * .079), 2.1*sin(z * .127));
    return p1 - p2;
}

float fragtail(vec3 q, float z) {
    vec3 pos = q;

    float scale = 3.5;
 	vec3 cxz = vec3(2.5+2.*cos(q.z*.15),3.,0);// vec3(4.,4.,1);//2.+1.*sin(q.z*.23)

    float r = length(pos);
    float s = 1.55;
    for (float i = 0.;i<2.;i++) {
        pos=abs(pos)-1.25;

        if ( pos.x- pos.y<0.) pos.yx = pos.xy;
        if ( pos.x- pos.z<0.) pos.zx = pos.xz;
        if ( pos.y- pos.z<0.) pos.zy = pos.yz;

        pos.x=scale * pos.x-cxz.x;
        pos.y=scale * pos.y-cxz.y;
        pos.z=scale * pos.z+1.;

        r = box(pos,vec3(qt,.25,sp));

        s *=.75/scale;
    }

    return (r*s);
}

vec2 map(vec3 p, int ix) {
    vec2 res = vec2(1e5,0);

 	vec2 tun = p.xy - path(p.z);
    vec3 q = vec3(tun,p.z);

    float id = floor((q.z+hf)/sp);
    q.z = mod(q.z+hf,sp)-hf;
    vec3 r = q; r.xy *= rz;

    float val = mod(id,6.)<3.?6.:3.;
    pModPolar(r.xy,val);
    pModPolar(q.xy,6.);
    vec3 g = q;

    float bx = fragtail(q,1.);
    if(bx<res.x) { res = vec2(bx,1.); hit=q; }

    g.y=abs(g.y)-.75;
    float bz = box(g-vec3(2.25,0,0),vec3(.01,.2,sp));
    if(bz<res.x) { res = vec2(bz,2.); hit=g; }

    float bg = length(r.xz-vec2(.75+.22*sin(T),0));
    if(bg<res.x && mod(id,3.)==0.&& ix==0 ) {
        res = vec2(bg,3.); 
        glow += .00065/(.0025+bg*bg);
    }

    return res;
}

vec3 normal(vec3 p, float t)
{
    float e = .001*t;
    vec2 h =vec2(1,-1)*.5773;
    vec3 n = h.xyy * map(p+h.xyy*e,3).x+
             h.yyx * map(p+h.yyx*e,3).x+
             h.yxy * map(p+h.yxy*e,3).x+
             h.xxx * map(p+h.xxx*e,3).x;
    return normalize(n);
}

vec3 clx = vec3(1);
vec4 FC = vec4(vec3(.1),0.);
vec4 render(inout vec3 ro, inout vec3 rd, inout vec3 ref, int count, inout float d, vec2 F) {

    vec3 C = vec3(0), p = ro;
    float m = 0.;

    float dof = .001, dofdist = 1./6.;
    vec2 off=vec2(.05);

    for(int i=0;i<132;i++) {

        //modified jitter/dof 
        //@Nusan https://www.shadertoy.com/view/3sXyRN
        if(mod(float(i),2.)<1.){
            off = texture(iChannel1,F.xy/1024.).rg*2.-1.;
            vec2 fp = off*dof;
            ro.xz += fp*(d)*.05;
            rd.xy += fp*(d*d)*dofdist*.01;
        }

        p = ro + rd * d;
        vec2 ray = map(p, count);
        if(ray.x<MIN_DIST*d||d>MAX_DIST)break;
        d += i<32? ray.x*.25: ray.x;
        m  = ray.y;
    } 
    hp = hit;

    float alpha = 0.;
    if(d<MAX_DIST)
    {
        vec3 n = normal(p,d), lpos =  vec3(2,10,-(8.-travelSpeed));
        lpos.xy += path(lpos.z);
        vec3 l = normalize(lpos-p);

        float diff = clamp(dot(n,l),0.,1.);
        float shdw = 1.0;

        for( float t=.05; t < 16.; ) {
            float h = map(p + l*t,3).x;
            if( h<MIN_DIST ) { shdw = 0.; break; }
            shdw = min(shdw, 12.*h/t);
            t += h*.9;
            if( shdw<MIN_DIST || t>24. ) break;
        }
        diff = mix(diff,diff*shdw,.65);

        vec3 h = vec3(.05);

        if(m==1.) {
            h=mix(vec3(.125),vec3(.425),.5+.5*sin(p.z*.0935));
            ref=h*.55;
        }
        if(m==2.) {
            h=mix(vec3(.7,.0,.2),vec3(.2,.0,.7),.5+.5*sin(p.z*.25));

            vec2 id = floor(hp.yz*5.45), uv = fract(hp.yz*5.45)-.5;
            float rnd = hash21(id), px = 4./R.x;

            if(rnd>.5)uv.x=-uv.x;
            vec2 q = length(uv-.5) < length(uv+.5) ? uv-.5 : uv+.5;
            float d = length(q)-.5;

            if(fract(rnd*43.32)>.65) d=min(length(uv.x),length(uv.y));

            float tx = .11+.075*sin(p.z*.15);
            h=mix(h,vec3(.8),smoothstep(px,-px,abs(d)-tx));  

            ref = mix(h*.75,h*.01,smoothstep(px,-px,abs(d)-tx)); 
        }

        C = m==3.? vec3(.5) : h*diff;
        C = mix(FC.rgb,C,  exp(-.0001*d*d*d));

        ro = p+n*.01;
        rd = reflect(rd,n);

    } else {
        C = FC.rgb;
    } 
    return vec4(C,alpha);
}

void mainImage( out vec4 O, in vec2 F )
{
    rz=rot(T*.5);
    travelSpeed = T*2.45; 

    vec2 uv = (2.*F.xy-R.xy)/max(R.x,R.y);
    vec3 lp = vec3(0,0,-travelSpeed);
    vec3 ro = vec3(0,0,.5);

    float x = M.z<0.||M.xy == vec2(0) ? 0. : -(M.y/R.y * 1. - .5) * PI;
    float y = M.z<0.||M.xy == vec2(0) ? 0. :  (M.x/R.x * 1. - .5) * PI;

    mat2 rx = rot(x), ry = rot(y);
    ro.yz *= rx,ro.xz *= ry;

    ro += lp; 
    lp.xy += path(lp.z);
    ro.xy += path(ro.z);

    vec3 f = normalize(lp-ro),
         r = normalize(cross(vec3(0,1,0),f)),
         u = normalize(cross(f,r)),
         c = ro+f*.575,
         i = c+uv.x*r+uv.y*u,
        rd = i-ro;

    vec3 C = vec3(0), ref = vec3(0), fil = vec3(1);

    float d = 0., a = 0.;
    int numBounces = 2;

    for(int i=0; i<numBounces; i++) {
        d =0.;
        vec4 pass = render(ro, rd, ref, i, d,F);
        C += pass.rgb*fil;
        sglow = glow;
        fil *= ref;
        if(i==0) { a = d; }
    }
    // fake tv static
    C = mix(C,clamp(C+.0185,vec3(0),vec3(1)),hash21(uv+fract(floor(T*20.)*423.23)));
    // fog and glow
    C = mix(FC.rgb,C,  exp(-.00015*a*a*a));
    C = mix(C,vec3(.2,.9,.9)*sglow,clamp(sglow,.0,.8)); 
    // gamma correction
    C = pow(C, vec3(.4545));
    O = vec4(C,1.0);
}
